CREATE FUNCTION public.change_invoice_number(p_order_id uuid,p_number text,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; BEGIN IF NOT public.is_master() OR NOT public.can_access('orders') OR length(btrim(COALESCE(p_reason,'')))=0 OR length(btrim(COALESCE(p_number,'')))=0 THEN RAISE EXCEPTION 'Master, nomor dan alasan wajib'; END IF; SELECT * INTO o FROM public.orders WHERE id=p_order_id AND tenant_id=public.active_tenant_id() AND deleted_at IS NULL FOR UPDATE; IF o.id IS NULL OR o.invoice_state='cancelled' THEN RAISE EXCEPTION 'Invoice tidak ditemukan atau dibatalkan'; END IF; UPDATE public.orders SET invoice_number=btrim(p_number) WHERE id=o.id; IF o.invoice_state='issued' THEN PERFORM public.sync_invoice_receivable(o.id); END IF; INSERT INTO public.audit_logs(tenant_id,actor_id,action,entity_type,entity_id,diff) VALUES(o.tenant_id,auth.uid(),'manual_invoice_number','orders',o.id,jsonb_build_object('before',o.invoice_number,'after',btrim(p_number),'reason',btrim(p_reason))); END $$;
GRANT EXECUTE ON FUNCTION public.change_invoice_number(uuid,text,text) TO authenticated; REVOKE EXECUTE ON FUNCTION public.change_invoice_number(uuid,text,text) FROM PUBLIC,anon;
CREATE OR REPLACE FUNCTION public.guard_order_discount() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RETURN NEW; END $$;
ALTER TABLE public.order_items ADD CONSTRAINT order_item_discount_limit CHECK((discount_type='percent' AND discount_value<=100) OR (discount_type='amount' AND discount_value<=qty*price));
ALTER TABLE public.quotation_items ADD CONSTRAINT quotation_item_discount_limit CHECK((discount_type='percent' AND discount_value<=100) OR (discount_type='amount' AND discount_value<=qty*price));
ALTER TABLE public.orders ADD CONSTRAINT order_document_discount_limit CHECK(discount_type<>'percent' OR discount_value<=100);
ALTER TABLE public.quotations ADD CONSTRAINT quotation_document_discount_limit CHECK(discount_type<>'percent' OR discount_value<=100);
CREATE FUNCTION public.immutable_issued_brand() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.issued_at IS NOT NULL AND (NEW.brand_snapshot IS DISTINCT FROM OLD.brand_snapshot OR NEW.invoice_date IS DISTINCT FROM OLD.invoice_date OR NEW.client_name IS DISTINCT FROM OLD.client_name OR NEW.discount_type IS DISTINCT FROM OLD.discount_type OR NEW.discount_value IS DISTINCT FROM OLD.discount_value OR NEW.tax_enabled IS DISTINCT FROM OLD.tax_enabled OR NEW.tax_rate IS DISTINCT FROM OLD.tax_rate) THEN RAISE EXCEPTION 'Snapshot dan nilai invoice terbit terkunci'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_issued_brand BEFORE UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.immutable_issued_brand();
CREATE FUNCTION public.archive_sales_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.invoice_state='issued' AND NEW.deleted_at IS DISTINCT FROM OLD.deleted_at AND NEW.deleted_at IS NOT NULL THEN RAISE EXCEPTION 'Batalkan invoice melalui persetujuan sebelum arsip'; END IF; RETURN NEW; END $$;
CREATE TRIGGER archive_sales_guard BEFORE UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.archive_sales_guard();
CREATE FUNCTION public.issued_item_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.orders WHERE id=NEW.order_id AND tenant_id=NEW.tenant_id AND issued_at IS NOT NULL) AND (TG_OP='INSERT' OR NEW.item_name IS DISTINCT FROM OLD.item_name OR NEW.qty IS DISTINCT FROM OLD.qty OR NEW.price IS DISTINCT FROM OLD.price OR NEW.discount_value IS DISTINCT FROM OLD.discount_value OR NEW.discount_type IS DISTINCT FROM OLD.discount_type OR (NEW.deleted_at IS DISTINCT FROM OLD.deleted_at AND EXISTS(SELECT 1 FROM public.orders WHERE id=NEW.order_id AND invoice_state='issued'))) THEN RAISE EXCEPTION 'Item invoice terbit terkunci'; END IF; RETURN NEW; END $$;
CREATE TRIGGER issued_item_guard BEFORE INSERT OR UPDATE ON public.order_items FOR EACH ROW EXECUTE FUNCTION public.issued_item_guard();
CREATE OR REPLACE FUNCTION public.create_shipment_atomic(p_order_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; sid uuid; tid uuid:=public.active_tenant_id(); BEGIN IF NOT public.can_access_tenant_module(tid,'shipments') OR NOT public.can_access_tenant_module(tid,'orders') THEN RAISE EXCEPTION 'Order dan Pengiriman wajib berizin'; END IF; SELECT * INTO o FROM public.orders WHERE id=p_order_id AND tenant_id=tid AND deleted_at IS NULL FOR UPDATE; IF o.id IS NULL OR o.invoice_state<>'issued' THEN RAISE EXCEPTION 'Invoice harus terbit sebelum pengiriman'; END IF; SELECT id INTO sid FROM public.shipments WHERE order_id=o.id AND tenant_id=tid AND deleted_at IS NULL ORDER BY created_at LIMIT 1; IF sid IS NOT NULL THEN RETURN sid; END IF; INSERT INTO public.shipments(tenant_id,order_id,ship_to,section,do_number,delivery_date,stored_by,delivery_by) VALUES(tid,o.id,o.client_name,o.section,replace(replace(o.invoice_number,'/INV/','/DO/'),'INV/','DO/'),(now() AT TIME ZONE 'Asia/Jakarta')::date,o.created_by,o.created_by) RETURNING id INTO sid; RETURN sid; END $$;
CREATE OR REPLACE FUNCTION public.list_archive() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE tbl text; rows jsonb; result jsonb:='[]'::jsonb; BEGIN IF NOT public.is_master() THEN RAISE EXCEPTION 'Khusus Master'; END IF; FOREACH tbl IN ARRAY ARRAY['clients','orders','order_items','quotations','quotation_items','shipments','pricelist_items','payables','receivables','cash_requests','expenses','tasks','team_members'] LOOP EXECUTE format('SELECT COALESCE(jsonb_agg(jsonb_build_object(''entity_type'',%L,''id'',id,''label'',COALESCE(to_jsonb(r)->>''name'',to_jsonb(r)->>''client_name'',to_jsonb(r)->>''item_name'',to_jsonb(r)->>''vendor'',to_jsonb(r)->>''purpose'',to_jsonb(r)->>''description'',to_jsonb(r)->>''title'',to_jsonb(r)->>''ship_to'',id::text),''deleted_at'',deleted_at,''reason'',delete_reason)),''[]''::jsonb) FROM public.%I r WHERE tenant_id=$1 AND deleted_at IS NOT NULL',tbl,tbl) INTO rows USING public.active_tenant_id(); result:=result||rows; END LOOP; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.restore_entity(p_entity_type text,p_entity_id uuid,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid:=public.active_tenant_id(); parent uuid; BEGIN IF NOT public.is_master() OR public.entity_module(p_entity_type) IS NULL THEN RAISE EXCEPTION 'Khusus Master'; END IF; IF length(btrim(COALESCE(p_reason,'')))=0 THEN RAISE EXCEPTION 'Alasan wajib'; END IF; IF p_entity_type IN ('order_items','shipments') THEN EXECUTE format('SELECT order_id FROM public.%I WHERE id=$1 AND tenant_id=$2',p_entity_type) INTO parent USING p_entity_id,tid; IF NOT EXISTS(SELECT 1 FROM public.orders WHERE id=parent AND tenant_id=tid AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Pulihkan order dahulu'; END IF; ELSIF p_entity_type='quotation_items' THEN SELECT quotation_id INTO parent FROM public.quotation_items WHERE id=p_entity_id AND tenant_id=tid; IF NOT EXISTS(SELECT 1 FROM public.quotations WHERE id=parent AND tenant_id=tid AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Pulihkan penawaran dahulu'; END IF; END IF; EXECUTE format('UPDATE public.%I SET deleted_at=NULL,deleted_by=NULL,delete_reason=NULL WHERE id=$1 AND tenant_id=$2 AND deleted_at IS NOT NULL',p_entity_type) USING p_entity_id,tid; INSERT INTO public.audit_logs(tenant_id,actor_id,action,entity_type,entity_id,diff) VALUES(tid,auth.uid(),'restore_reason',p_entity_type,p_entity_id,jsonb_build_object('reason',p_reason)); END $$;